#!/usr/bin/env python3
"""Build solution.json from per-video ledgers.

Each ledger_X.json: {video, initial_state[11], checkpoints:[{time_s, state_after[11], ...}]}
changes[] are derived deterministically from consecutive state vectors:
  component i, value transition prev->cur:
    0 -> 1 : install        step 3*i
    0 -> -1: incorrect      step 3*i+1
   -1 -> 1 : (fix) install   step 3*i        (became correctly installed)
    1 -> -1: reinstall wrong step 3*i+1
    1 -> 0 : remove          step 3*i+2
   -1 -> 0 : remove          step 3*i+2  (incorrect->absent uses normal removal id)
"""
import json, sys, os

COMP = ["base","front chassis","front chassis pin","rear chassis","short rear chassis",
        "front-rear chassis pin","rear-rear chassis pin","front bracket",
        "front bracket screw","front wheel assy","rear wheel assy"]

def step_for(i, prev, cur):
    if prev == cur:
        return None
    if cur == 1:      # became correct (from 0 or -1)
        return 3*i
    if cur == -1:     # became incorrect (from 0 or 1)
        return 3*i+1
    if cur == 0:      # removed (from 1 or -1)
        return 3*i+2
    raise ValueError

def diff_changes(prev, cur):
    ch = []
    for i in range(11):
        s = step_for(i, prev[i], cur[i])
        if s is not None:
            ch.append(s)
    return sorted(set(ch))

def main():
    ledger_dir = "/workspace/work"
    videos = ["A","B","C","D","E","F","G"]
    all_ck = []
    problems = []
    for v in videos:
        p = os.path.join(ledger_dir, f"ledger_{v}.json")
        if not os.path.exists(p):
            problems.append(f"MISSING ledger_{v}.json")
            continue
        d = json.load(open(p))
        init = d["initial_state"]
        assert len(init)==11, f"{v} initial len"
        prev = init
        cks = sorted(d["checkpoints"], key=lambda c: c["time_s"])
        for c in cks:
            cur = c["state_after"]
            if len(cur)!=11:
                problems.append(f"{v} @{c['time_s']} bad len"); continue
            ch = diff_changes(prev, cur)
            if not ch:
                problems.append(f"{v} @{c['time_s']} NO CHANGE vs prev (dropping)")
                continue
            all_ck.append({"video":v,"time_s":round(float(c["time_s"]),1),
                           "changes":ch,"state_after":[int(x) for x in cur]})
            prev = cur
    all_ck.sort(key=lambda c:(c["video"], c["time_s"]))
    out = {"checkpoints": all_ck}
    json.dump(out, open("/workspace/output/solution.json","w"), indent=2)
    print("wrote solution.json with", len(all_ck), "checkpoints")
    for v in videos:
        n = sum(1 for c in all_ck if c["video"]==v)
        print(f"  {v}: {n}")
    if problems:
        print("PROBLEMS:")
        for x in problems: print("  -", x)

if __name__=="__main__":
    main()

